pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        GlpManagerStub stub = new GlpManagerStub();
        c.initialize(
            IERC20Like(address(1)),
            IERC20Like(address(2)),
            IRewardRouterLike(address(3)),
            IGlpManagerLike(address(stub)),
            address(4),
            address(5)
        );
    }

    // General rule: for ANY fuzzed newOwner, if transferring ownership to newOwner
    // is rejected (i.e. newOwner == address(0)), the original owner must remain the
    // contract's sole owner and keep exclusive owner-only power (setKeeper succeeds);
    // if the transfer succeeded to a nonzero owner, the original owner must lose that
    // power. The buggy version accepts ownership transfer to address(0), so owner()
    // becomes address(0) and the original owner's owner-only call reverts.
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(this));

        // original owner (the test contract) attempts to transfer ownership
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {
            // transfer accepted
        } catch {
            // transfer rejected
        }

        // observe from the original owner's seat whether it retains owner-only power
        bool okKeeper;
        vm.prank(address(this));
        try c.setKeeper(newOwner) {
            okKeeper = true;
        } catch {
            okKeeper = false;
        }

        assertTrue(
            newOwner == address(0) ? okKeeper : !okKeeper,
            "original owner retains exclusive owner power: transfer to zero rejected, transfer to nonzero revokes power"
        );
    }
}

