pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // initialize through the raw public ABI so no external token contracts are needed;
        // owner (and keeper) become address(this)
        (bool okInit, ) = address(c).call(
            abi.encodeWithSignature(
                "initialize(address,address,address,address,address,address)",
                address(1), address(2), address(3), address(4), address(5), address(this)
            )
        );
        require(okInit, "init failed");
    }
    function testFuzz_property(address newOwner) public {
        vm.prank(address(this));
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("transferOwnership(address)", newOwner)
        );
        ok; // outcome flag available but the rule is stated over the resulting state
        address expected = newOwner == address(0) ? address(this) : newOwner;
        // General rule: after any owner-initiated transferOwnership, the zero address
        // never becomes the owner; ownership moves to newOwner iff nonzero, else stays.
        assertTrue(c.owner() == expected);
    }
}

