pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;

    function setUp() public {
        c = new C();
        originalOwner = address(this);
        GlpManagerStub glpManager = new GlpManagerStub();
        vm.prank(originalOwner);
        c.initialize(
            IERC20(address(1)),
            IERC20(address(2)),
            IRewardRouterV2(address(3)),
            IGlpManager(address(glpManager)),
            address(4),
            address(5)
        );
    }

    function testFuzz_property(address newOwner, address newKeeper) public {
        vm.assume(newOwner != address(this) || true);

        // Attempt the ownership handover from the current owner.
        bool handoverOk;
        vm.prank(originalOwner);
        try c.transferOwnership(newOwner) {
            handoverOk = true;
        } catch {
            handoverOk = false;
        }

        // Can the original owner still exercise owner-only power?
        bool originalCanAct;
        vm.prank(originalOwner);
        try c.setKeeper(newKeeper) {
            originalCanAct = true;
        } catch {
            originalCanAct = false;
        }

        // Can the recipient of the handover exercise owner-only power?
        bool newOwnerCanAct;
        vm.prank(newOwner);
        try c.setKeeper(newKeeper) {
            newOwnerCanAct = true;
        } catch {
            newOwnerCanAct = false;
        }

        // General rule: an ownership handover may never leave the contract ownerless —
        // if the handover succeeded, the recipient (nonzero in the correct contract)
        // must be able to act; if it was rejected, the original owner must still act.
        assertTrue(
            (handoverOk && newOwnerCanAct) || (!handoverOk && originalCanAct),
            "ownership handover must preserve exercisable owner power"
        );
    }
}

