        vm.assume(keeper != address(0));
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint128).max);

        Erc20Dummy usdc = new Erc20Dummy();
        Erc20Dummy sGlp = new Erc20Dummy();
        RewardRouterDummy rr = new RewardRouterDummy();
        GlpManagerDummy gm = new GlpManagerDummy();

